# ================= EPD 驱动 =================
busy = machine.Pin(7, machine.Pin.IN, machine.Pin.PULL_UP)
rst = machine.Pin(8, machine.Pin.OUT, value=1)
dc = machine.Pin(9, machine.Pin.OUT, value=1)
cs = machine.Pin(10, machine.Pin.OUT, value=1)
spi = machine.SoftSPI(baudrate=2000000, polarity=0, phase=0,
                      sck=machine.Pin(12), mosi=machine.Pin(11), miso=machine.Pin(6))


def wait_busy(ms=60000):
    t = time.ticks_ms()
    while busy.value():
        if time.ticks_diff(time.ticks_ms(), t) > ms:
            raise RuntimeError("BUSY timeout")
        time.sleep_ms(5)


def cmd(c, data=None):
    dc.value(0)
    cs.value(0)
    spi.write(bytes((c,)))
    if data is not None:
        dc.value(1)
        spi.write(data)
    cs.value(1)
    dc.value(1)


def reset():
    rst.value(0)
    time.sleep_ms(10)
    rst.value(1)
    time.sleep_ms(10)
    wait_busy()


def init():
    reset()
    cmd(0x01, b"\x8f\x01\x00")
    cmd(0x21, b"\x00\x00")
    cmd(0x3C, b"\x05")
    cmd(0x11, b"\x03")
    cmd(0x18, b"\x80")
    cmd(0x22, b"\xf7")
    time.sleep_ms(50)


def window():
    cmd(0x44, b"\x00\x31")
    cmd(0x45, b"\x00\x00\x2b\x01")
    cmd(0x4E, b"\x00")
    cmd(0x4F, b"\x00\x00")


def refresh():
    cmd(0x20)
    wait_busy()
    cmd(0x02)
    wait_busy()
    cmd(0x07, b"\x03")


def conv_bw(fb):
    for i in range(N):
        fb[i] ^= 0xFF
    return fb


def conv_red(fr):
    return fr


# ================= 画布(位1=黑墨/红墨; 'w'=在黑底上挖白) =================
class Canvas:
    def __init__(self):
        self.fb = bytearray(N)
        self.fr = bytearray(N)

    def _set(self, buf, x, y):
        if 0 <= x < W and 0 <= y < H:
            buf[y * RB + (x >> 3)] |= 0x80 >> (x & 7)

    def _clr(self, x, y):
        if 0 <= x < W and 0 <= y < H:
            i = y * RB + (x >> 3)
            m = (0x80 >> (x & 7)) ^ 0xFF
            self.fb[i] &= m
            self.fr[i] &= m

    def text(self, font, s, x, y, color="k"):
        cx = x
        for ch in s:
            g = font.get(ch)
            if g is None:
                cx += 8
                continue
            w, h, dy, data = g[0], g[1], g[2], g[3:]
            bw = (w + 7) >> 3
            if color == "w":
                for ry in range(h):
                    row = y + dy + ry
                    if row < 0 or row >= H:
                        continue
                    for xb in range(w):
                        if data[ry * bw + (xb >> 3)] & (0x80 >> (xb & 7)):
                            self._clr(cx + xb, row)
            else:
                buf = self.fr if color == "r" else self.fb
                for ry in range(h):
                    row = y + dy + ry
                    if row < 0 or row >= H:
                        continue
                    base = row * RB
                    for xb2 in range(bw):
                        v = data[ry * bw + xb2]
                        if not v:
                            continue
                        px = cx + xb2 * 8
                        bi = px >> 3
                        sh = px & 7
                        if bi < RB:
                            buf[base + bi] |= v >> sh
                        if sh and bi + 1 < RB:
                            buf[base + bi + 1] |= (v << (8 - sh)) & 0xFF
            cx += w

    def rect(self, x0, y0, x1, y1, color="k"):
        for y in range(int(y0), int(y1) + 1):
            for x in range(int(x0), int(x1) + 1):
                if color == "w":
                    self._clr(x, y)
                else:
                    self._set(self.fr if color == "r" else self.fb, x, y)

    def hline(self, x0, x1, y, color="k", w=2, dash=0):
        for t in range(w):
            for x in range(int(x0), int(x1) + 1):
                if not dash or (x // dash) % 2 == 0:
                    self._set(self.fr if color == "r" else self.fb, x, y + t)

    def vline(self, x, y0, y1, color="k", w=1, dash=0):
        for t in range(w):
            for y in range(int(y0), int(y1) + 1):
                if not dash or (y // dash) % 2 == 0:
                    self._set(self.fr if color == "r" else self.fb, x + t, y)

    def dot(self, cx, cy, r, color="k"):
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if dx * dx + dy * dy <= r * r:
                    self._set(self.fr if color == "r" else self.fb, cx + dx, cy + dy)

    def polyline(self, pts, color="k", w=1):
        for i in range(len(pts) - 1):
            x0, y0 = pts[i][0], pts[i][1]
            x1, y1 = pts[i + 1][0], pts[i + 1][1]
            dx = abs(x1 - x0)
            dy = -abs(y1 - y0)
            sx = 1 if x0 < x1 else -1
            sy = 1 if y0 < y1 else -1
            err = dx + dy
            while True:
                self.dot(x0, y0, w, color)
                if x0 == x1 and y0 == y1:
                    break
                e2 = 2 * err
                if e2 >= dy:
                    err += dy
                    x0 += sx
                if e2 <= dx:
                    err += dx
                    y0 += sy


F = {"s": S, "m": M, "d": D}

# 画布接口: text(font,s,x,y,color) rect(...) hline(...) vline(...) polyline(...) dot(...)
# color: 'k' 黑 / 'r' 红 / 'w' 白(在黑底上挖字)

W, H = 400, 300
ML = 14                 # 左右安全边
DIV_RED_Y = 30          # 头部红色分隔线
STRIP_X0 = 6            # 七列起点
STRIP_W = 388.0 / 7     # 单列宽
LBL_Y = 37              # 星期标签顶(16px字, 底=53 与日期行留1px)
DATE_Y = 54             # 日期数字顶(30px 字)
BOX_Y0, BOX_Y1 = 33, 91 # 今日高亮块
BAR_Y = 94              # 今日红色下划条
WEATHER_Y = 98          # 天气词行(今日列留空, 头部已显示当前天气)
GUIDE_Y0, GUIDE_Y1 = 116, 238   # 导轨下移, 给天气词行让位
PLOT_X0, PLOT_X1 = 46, 386
PLOT_Y0, PLOT_Y1 = 126, 232
RED_LINE2 = 244         # 底部红色分隔线
FOOT_LBL_Y = 251        # 底部标签(16px字, 底=267 与数值行留1px)
FOOT_VAL_Y = 268        # 底部数值
FOOT_BOT = 288


def tw(font, s):
    w = 0
    for ch in s:
        g = font.get(ch)
        w += g[0] if g else 8
    return w


def tc(cv, font, s, cx, y, color):
    """水平居中绘制"""
    cv.text(font, s, int(cx - tw(font, s) / 2), y, color)


def tr(cv, font, s, xr, y, color):
    """右对齐绘制(xr=右边界)"""
    cv.text(font, s, int(xr - tw(font, s)), y, color)


def cx_of(i):
    return STRIP_X0 + STRIP_W * (i + 0.5)


def render(cv, F, d):
    """d = {city,date:(y,m,d,wday),cur:(temp,cond),days:[(m,d,wday,tmax,tmin)],
            sun:(sr,ss),hum,upd}"""
    S, M, D = F["s"], F["m"], F["d"]

    # ---------- 头部: 左=城市/日期/星期, 右=天气/当前温度 ----------
    y, mo, dd, wd = d["date"]
    x = ML
    cv.text(M, d["city"], x, 8, "k")
    x += tw(M, d["city"]) + 10
    dv = "%d月%d日" % (mo, dd)
    cv.text(M, dv, x, 8, "k")
    x += tw(M, dv) + 10
    cv.text(M, d["wk"], x, 8, "k")
    left_end = x + tw(M, d["wk"])

    cond, tcur = d["cur"][1], d["cur"][0]
    ts = "%d°" % tcur
    blockw = tw(M, cond) + 8 + tw(M, ts)
    rx = W - ML - blockw
    cv.text(M, cond, rx, 8, "k")
    cv.text(M, ts, rx + tw(M, cond) + 8, 8, "r")

    # 星期与天气之间的空档: 居中放农历(空间不够时去掉"农历"二字)
    lun = d.get("lunar", "")
    if lun and rx - left_end > 24:
        room = rx - left_end - 16
        if tw(M, lun) > room and lun.startswith("农历"):
            lun = lun[2:]
        if tw(M, lun) <= room:
            tc(cv, M, lun, (left_end + rx) // 2, 8, "k")

    cv.hline(ML, W - ML, DIV_RED_Y, "r", 2)

    # ---------- 七列日历条 ----------
    days = d["days"]
    for i, it in enumerate(days):
        dm = it[0]
        cx = cx_of(i)
        lbl = d["labels"][i]
        ds = "%d" % dm
        if i == 0:
            cv.rect(int(cx - 25), BOX_Y0, int(cx + 25), BOX_Y1 - 1, "w")
            cv.rect(int(cx - 25), BOX_Y0, int(cx + 25), BOX_Y1 - 1, "k")
            tc(cv, S, lbl, cx, LBL_Y, "w")
            tc(cv, D, ds, cx, DATE_Y, "w")
            cv.rect(int(cx - 25), BAR_Y, int(cx + 25), BAR_Y + 3, "r")
        else:
            tc(cv, S, lbl, cx, LBL_Y, "k")
            tc(cv, D, ds, cx, DATE_Y, "k")

    # ---------- 天气词行(今日列留空: 头部已显示当前天气与温度) ----------
    for i in range(1, len(days)):
        it = days[i]
        cond = it[4] if len(it) > 4 else ""
        if not cond:
            continue
        c = "r" if ("雨" in cond or "雪" in cond or "雷" in cond) else "k"
        tc(cv, S, cond, cx_of(i), WEATHER_Y, c)

    # ---------- 温度折线 ----------
    hi = max(it[2] for it in days)
    lo = min(it[3] for it in days)
    hi = int(hi + 0.999)
    lo = int(lo)
    span = max(hi - lo, 4)
    pad = (PLOT_Y1 - PLOT_Y0 - 30) / float(span)

    def py(t):
        return int(PLOT_Y1 - (t - lo) * pad - 15)

    # 竖向点线导轨
    for i in range(7):
        cv.vline(int(cx_of(i)), GUIDE_Y0, GUIDE_Y1, "k", 1, 4)

    # 横向刻度线 + 左侧刻度值
    for t in (hi, lo + (hi - lo) // 2, lo):
        yy = py(t)
        cv.hline(PLOT_X0, PLOT_X1, yy, "k", 1, 3)
        tr(cv, S, "%d°" % t, PLOT_X0 - 6, yy - 7, "k")

    # 最高温(红) / 最低温(黑)
    pts_hi = [(int(cx_of(i)), py(days[i][2])) for i in range(7)]
    pts_lo = [(int(cx_of(i)), py(days[i][3])) for i in range(7)]
    cv.polyline(pts_hi, "r", 1)
    cv.polyline(pts_lo, "k", 1)
    for i in range(7):
        px, pyh = pts_hi[i]
        cv.dot(px, pyh, 2, "r")
        s = "%d°" % int(days[i][2] + 0.999)
        if i == 0:
            cv.text(M, s, px + 9, pyh - 22, "r")
        elif i == 6:
            tr(cv, M, s, px - 9, pyh - 22, "r")
        else:
            tc(cv, M, s, px, pyh - 22, "r")
        qx, pql = pts_lo[i]
        cv.dot(qx, pql, 2, "k")
        s = "%d°" % int(days[i][3])
        if i == 0:
            cv.text(M, s, qx + 9, pql + 6, "k")
        elif i == 6:
            tr(cv, M, s, qx - 9, pql + 6, "k")
        else:
            tc(cv, M, s, qx, pql + 6, "k")

    # ---------- 底部指标(4~5 项自适应列宽) ----------
    cv.hline(ML, W - ML, RED_LINE2, "r", 2)
    cols = [("日出", d["sun"][0]), ("日落", d["sun"][1]),
            ("湿度", "%d%%" % d["hum"])]
    if d.get("extra"):                     # 可选第五项: (标签, 数值)
        cols.append(tuple(d["extra"]))
    cols.append(("更新", d["upd"]))
    last = len(cols) - 1
    span_w = (W - 2 * ML) / float(len(cols))
    for k, (lbl, val) in enumerate(cols):
        cx = ML + span_w * (k + 0.5)
        tc(cv, S, lbl, cx, FOOT_LBL_Y, "k")
        tc(cv, M, val, cx, FOOT_VAL_Y, "r" if k == last else "k")
        if k:
            cv.vline(int(ML + span_w * k), FOOT_LBL_Y - 2, FOOT_BOT, "k", 1)


