LMONTHS = ('正', '二', '三', '四', '五', '六', '七', '八', '九', '十', '冬', '腊')
LNUM = ('一', '二', '三', '四', '五', '六', '七', '八', '九')


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def days_from_civil(y, m, d):
    n = 0
    for Y in range(1900, y):
        if _is_leap(Y):
            n += 1
    cum = (0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334)
    doy = cum[m - 1] + d - 1 + (1 if m > 2 and _is_leap(y) else 0)
    return (y - 1900) * 365 + n + doy


def leap_month(y):
    return LUNAR_INFO[y - 1900] & 0xF


def leap_days(y):
    if leap_month(y) != 0:
        return 30 if (LUNAR_INFO[y - 1900] & 0xF0000) else 29
    return 0


def month_days(y, m):
    return 30 if (LUNAR_INFO[y - 1900] & 0x0FFFF & (1 << (16 - m))) else 29


def year_days(y):
    s = 29 * 12
    i = 0x8000
    while i >= 0x8:
        if LUNAR_INFO[y - 1900] & 0xFFF0 & i:
            s += 1
        i >>= 1
    return s + leap_days(y)


def solar2lunar(y, m, d):
    offset = days_from_civil(y, m, d) - days_from_civil(1900, 1, 31)
    if offset < 0 or y < 1900 or y > 2100:
        return None
    ly = 1900
    while ly < 2100:
        t = year_days(ly)
        if offset < t:
            break
        offset -= t
        ly += 1
    leap = leap_month(ly)
    lm = 1
    leap_used = False
    while lm <= 12:
        if leap != 0 and not leap_used and lm == leap + 1:
            ld = leap_days(ly)
            if offset < ld:
                return ly, leap, offset + 1, leap, True
            offset -= ld
            leap_used = True
        ld = month_days(ly, lm)
        if offset < ld:
            return ly, lm, offset + 1, leap, False
        offset -= ld
        lm += 1
    return ly, 12, 30, leap, False


def lunar_day_str(d):
    if d == 10:
        return "初十"
    if d == 20:
        return "二十"
    if d == 30:
        return "三十"
    p = {1: "十", 2: "廿", 3: "三"}.get(d // 10, "初")
    return p + LNUM[d % 10 - 1]


def lunar_str(y, m, d):
    r = solar2lunar(y, m, d)
    if r is None:
        return ""
    ly, lm, ld, leap, lflag = r
    return "农历" + ("闰" if lflag else "") + LMONTHS[lm - 1] + "月" + lunar_day_str(ld)


# ================= 数据 =================
def http_get(url, timeout=15):
    try:
        parts = url.split("/", 3)
        host = parts[2]
        path = "/" + parts[3] if len(parts) > 3 else "/"
        ai = socket.getaddrinfo(host, 80)[0][-1]
        s = socket.socket()
        s.settimeout(timeout)
        s.connect(ai)
        s.send(("GET %s HTTP/1.0\r\nHost: %s\r\nUser-Agent: esp32-epd\r\n"
                "Connection: close\r\n\r\n" % (path, host)).encode())
        buf = bytearray()
        while True:
            d = s.recv(1024)
            if not d:
                break
            buf += d
            if len(buf) > 65536:
                break
        s.close()
        i = bytes(buf).find(b"\r\n\r\n")
        if i < 0:
            return None
        return bytes(buf[i + 4:]).decode("utf-8", "ignore")
    except Exception as e:
        print("[http]", e)
        return None


def hhmm(s):
    i = s.find("T")
    return s[i + 1:i + 6] if i >= 0 else s


def fetch():
    body = http_get(API)
    if not body:
        return None
    try:
        j = ujson.loads(body)
        dly = j["daily"]
        cur = j["current"]
        days = []
        for i in range(7):
            days.append((int(dly["time"][i][8:10]), 0,
                         float(dly["temperature_2m_max"][i]),
                         float(dly["temperature_2m_min"][i]),
                         WMO.get(int(dly["weather_code"][i]), "")))
        return {"days": days,
                "cur": (int(float(cur["temperature_2m"]) + 0.5),
                        WMO.get(int(cur["weather_code"]), "阴")),
                "sun": (hhmm(dly["sunrise"][0]), hhmm(dly["sunset"][0])),
                "hum": int(float(cur["relative_humidity_2m"]) + 0.5),
                "pop": int(dly["precipitation_probability_max"][0])}
    except Exception as e:
        print("[parse]", e)
        return None


def save_cache(f):
    try:
        with open(CACHE, "w") as fp:
            fp.write(ujson.dumps(f))
    except Exception as e:
        print("[cache]", e)


def load_cache():
    try:
        with open(CACHE) as fp:
            return ujson.loads(fp.read())
    except Exception:
        return None


def fallback():
    lt = time.localtime(time.time() + TZ)
    mo, dd = lt[1], lt[2]
    days = []
    for i in range(7):
        d2 = dd + i
        m2 = mo
        while d2 > 30:
            d2 -= 30
            m2 += 1
        days.append((d2, 0, 18, 10, ""))
    return {"cur": (15, "阴"), "sun": ("06:20", "17:03"), "hum": 50,
            "pop": 30, "days": days}


def build_data(f):
    lt = time.localtime(time.time() + TZ)
    y, mo, dd, wd = lt[0], lt[1], lt[2], lt[6]
    labels = ["今天", "明天"] + ["周" + WK[(wd + i) % 7] for i in range(2, 7)]
    return {"city": CITY, "wk": "周" + WK[wd], "date": (y, mo, dd, wd),
            "cur": f["cur"], "labels": labels,
            # 旧缓存(4元组)兼容: 缺天气词时补空串, 该列不画天气
            "days": [it if len(it) > 4 else (it[0], it[1], it[2], it[3], "")
                     for it in f["days"]],
            "sun": f["sun"], "hum": f["hum"], "lunar": lunar_str(y, mo, dd),
            # 第五项: 今日降水概率(旧缓存无 pop 字段时自动退回四列)
            "extra": ("降水", "%d%%" % f["pop"]) if "pop" in f else None,
            "upd": "%02d:%02d" % (lt[3], lt[4])}


def draw(d):
    gc.collect()
    cv = Canvas()
    render(cv, F, d)
    init()
    window()
    cmd(0x24, conv_bw(cv.fb))
    window()
    cmd(0x26, conv_red(cv.fr))
    refresh()
    gc.collect()


def wifi_up():
    w = network.WLAN(network.STA_IF)
    w.active(True)
    if w.isconnected():
        return True
    try:
        w.disconnect()
    except Exception:
        pass
    time.sleep(0.5)
    w.connect(SSID, PWD)
    t = time.ticks_ms()
    while not w.isconnected():
        if time.ticks_diff(time.ticks_ms(), t) > 20000:
            return False
        time.sleep_ms(300)
    return True


def ntp_sync():
    import ntptime
    for host in ("cn.pool.ntp.org", "ntp.aliyun.com", "pool.ntp.org"):
        try:
            ntptime.host = host
            ntptime.settime()
            print("[ntp] ok via", host)
            return True
        except Exception as e:
            print("[ntp] fail", host, e)
    return False


def main():
    print("[boot] week board start")
    gc.collect()
    have_net = wifi_up()
    print("[wifi]", "ok" if have_net else "FAILED")
    if have_net:
        ntp_sync()
    f = fetch() if have_net else None
    if f:
        print("[wx] ok")
        save_cache(f)
    else:
        f = load_cache()
        print("[wx]", "cache" if f else "fallback")
        if not f:
            f = fallback()
    draw(build_data(f))
    if OFFGRID:
        machine.deepsleep(REFRESH_MIN * 60 * 1000)
    nxt = time.time() + REFRESH_MIN * 60
    last_day = time.localtime(time.time() + TZ)[2]
    while True:
        time.sleep(30)
        lt = time.localtime(time.time() + TZ)
        if time.time() < nxt and lt[2] == last_day:
            continue
        last_day = lt[2]
        if wifi_up():
            f2 = fetch()
            if f2:
                save_cache(f2)
                f = f2
        draw(build_data(f))
        nxt = time.time() + REFRESH_MIN * 60


main()
